def digest(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()

def ev(path, start, end, note, previous=False):
    absolute = (PREVIOUS if previous else ROOT) / path
    lines = absolute.read_text().splitlines()
    assert 1 <= start <= end <= len(lines), (path, start, end, len(lines))
    return {'path': path, 'absolute_path': str(absolute), 'line_start': start,
            'line_end': end, 'sha256': digest(absolute), 'note': note,
            'origin': 'previous_audit' if previous else 'source'}

def find_ev(path, fragment, note, after=0, before=0):
    lines = (ROOT/path).read_text().splitlines()
    idx = next(i for i,l in enumerate(lines) if fragment in l)
    return ev(path, max(1, idx+1-before), min(len(lines), idx+1+after), note)

