findings = []
def add(id, severity, title, summary, functions, evidence, preconditions, scenario,
        impact, protections, limits, previous, acceptance, docs=()):
    histories = {sig: inventory['function_histories'].get(sig, []) for sig in functions}
    findings.append({
        'id':id, 'severity':severity, 'title':title, 'status':'static_confirmed',
        'runtime_tested':False, 'source_head':HEAD, 'summary':summary,
        'effective_source_definitions':{sig:inventory['candidate_final_functions'].get(sig) for sig in functions},
        'definition_histories':histories, 'evidence':evidence,
        'preconditions':preconditions, 'failure_scenario':scenario, 'impact':impact,
        'existing_protections_and_consumer_checks':protections,
        'runtime_unknowns_and_limits':limits, 'previous_audit_crosswalk':previous,
        'acceptance_criteria':acceptance, 'primary_source_ids':list(docs),
    })

